const fs = require("fs");
const path = require("path");

const ROOT = "C:\\Users\\edmem\\OneDrive\\Desktop\\Video Projects\\first-video\\edit\\animations";

// Icons: 24x24 viewBox, drawn with currentColor
const ICONS = {
  app: `<path d="M5 5h5v5H5V5zm9 0h5v5h-5V5zM5 14h5v5H5v-5zm9 0h5v5h-5v-5z"/>`,
  rocket: `<path d="M13.13 2.87a6.7 6.7 0 0 1 4.6 1.85 6.7 6.7 0 0 1 1.85 4.6c0 2.6-1.4 5.2-3.9 7.2l.1 2.3a1 1 0 0 1-1.7.76l-1.9-1.83c-.5.1-1 .15-1.5.15s-1-.05-1.5-.15L7.3 19.6a1 1 0 0 1-1.7-.76l.1-2.3c-2.5-2-3.9-4.6-3.9-7.2a6.7 6.7 0 0 1 1.85-4.6 6.7 6.7 0 0 1 4.6-1.85c1.6 0 3.15.4 4.4 1.2a9.4 9.4 0 0 1 .48-1.2zM12 8.2a2.1 2.1 0 1 0 0 4.2 2.1 2.1 0 0 0 0-4.2zM5.4 17.6l-1.9 3.6 3.6-1.9-1.7-1.7z"/>`,
  warning: `<path d="M12 2.5 23 21H1L12 2.5zm0 6.2a1.1 1.1 0 0 0-1.1 1.1v4.4a1.1 1.1 0 0 0 2.2 0v-4.4A1.1 1.1 0 0 0 12 8.7zm0 8.4a1.3 1.3 0 1 0 0 2.6 1.3 1.3 0 0 0 0-2.6z"/>`,
  bell: `<path d="M12 2.5a1.4 1.4 0 0 1 1.4 1.4v.6a6.3 6.3 0 0 1 4.6 6.06v3.2l1.8 3.04a1 1 0 0 1-.86 1.5H5.06a1 1 0 0 1-.86-1.5L6 13.76v-3.2A6.3 6.3 0 0 1 10.6 4.5v-.6A1.4 1.4 0 0 1 12 2.5zm-2.4 17.2a2.4 2.4 0 0 0 4.8 0h-4.8z"/>`,
  sparkle: `<path d="M12 2.2 13.7 9l6.8 1.7-6.8 1.7L12 19.2 10.3 12.4 3.5 10.7 10.3 9 12 2.2zM19.2 15.4l.85 2.6 2.6.85-2.6.85-.85 2.6-.85-2.6-2.6-.85 2.6-.85.85-2.6z"/>`,
};

const TAGS = [
  {
    dir: "slot_tag_nexion",
    id: "slot_tag_nexion",
    title: "Tag - Nexion",
    label: "NEXION",
    icon: ICONS.app,
    a1: "#ff7aa8",
    a2: "#ffb37a",
    a3: "#cf3fc4",
    duration: 2.6,
    pulse: false,
  },
  {
    dir: "slot_tag_rocket",
    id: "slot_tag_rocket",
    title: "Tag - Rocket.new",
    label: "ROCKET.NEW",
    icon: ICONS.rocket,
    a1: "#ff7aa8",
    a2: "#ffb37a",
    a3: "#cf3fc4",
    duration: 2.6,
    pulse: false,
  },
  {
    dir: "slot_tag_bug",
    id: "slot_tag_bug",
    title: "Tag - Bug Found",
    label: "BUG FOUND",
    icon: ICONS.warning,
    a1: "#ff6a5c",
    a2: "#ffb37a",
    a3: "#e0333f",
    duration: 2.1,
    pulse: false,
  },
  {
    dir: "slot_tag_subscribe",
    id: "slot_tag_subscribe",
    title: "Tag - Subscribe",
    label: "SUBSCRIBE",
    icon: ICONS.bell,
    a1: "#ff7aa8",
    a2: "#ffb37a",
    a3: "#cf3fc4",
    duration: 2.6,
    pulse: true,
  },
  {
    dir: "slot_tag_promptbox",
    id: "slot_tag_promptbox",
    title: "Tag - New Prompt Box",
    label: "NEW: AI PROMPT BOX",
    icon: ICONS.sparkle,
    a1: "#ff7aa8",
    a2: "#ffb37a",
    a3: "#cf3fc4",
    duration: 2.6,
    pulse: false,
  },
];

function buildHtml(t) {
  const exitStart = (t.duration - 0.5).toFixed(2);
  const pulseBlock = t.pulse
    ? `
      // subtle icon pulse (call-to-action energy) -- eased, not linear
      tl.to("#tag-icon", { scale: 1.16, duration: 0.16, ease: "power2.out" }, 1.05);
      tl.to("#tag-icon", { scale: 1, duration: 0.24, ease: "power2.in" }, 1.21);
      tl.to("#tag-icon", { scale: 1.1, duration: 0.14, ease: "power2.out" }, 1.55);
      tl.to("#tag-icon", { scale: 1, duration: 0.22, ease: "power2.in" }, 1.69);`
    : "";

  return `<!doctype html>
<html lang="en" data-resolution="landscape">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=1920, height=1080" />
    <title>${t.title}</title>
    <script src="https://cdn.jsdelivr.net/npm/gsap@3.14.2/dist/gsap.min.js"></script>
    <style>
      * {
        margin: 0;
        padding: 0;
        box-sizing: border-box;
      }
      html,
      body {
        margin: 0;
        width: 1920px;
        height: 1080px;
        overflow: hidden;
        background: transparent;
      }
      body {
        font-family: -apple-system, "Segoe UI", "Helvetica Neue", Arial, sans-serif;
      }

      #root {
        position: relative;
        width: 1920px;
        height: 1080px;
        background: transparent;
      }

      #overlay-wrap {
        position: absolute;
        inset: 0;
      }

      /* --- shared liquid-glass tag component --- */
      .tag-wrap {
        position: absolute;
        left: 90px;
        top: 856px;
      }

      .tag {
        position: relative;
        display: inline-flex;
        align-items: center;
        gap: 18px;
        padding: 20px 38px 20px 20px;
        border-radius: 48px;
        background: linear-gradient(
          135deg,
          rgba(255, 255, 255, 0.18) 0%,
          rgba(255, 255, 255, 0.06) 100%
        );
        -webkit-backdrop-filter: blur(22px) saturate(150%);
        backdrop-filter: blur(22px) saturate(150%);
        box-shadow:
          0 18px 50px rgba(0, 0, 0, 0.4),
          inset 0 1px 0 rgba(255, 255, 255, 0.45),
          inset 0 -1px 0 rgba(255, 255, 255, 0.05);
        overflow: hidden;
      }

      /* gradient border ring that catches light at an angle */
      .tag::before {
        content: "";
        position: absolute;
        inset: 0;
        border-radius: inherit;
        padding: 1.5px;
        background: linear-gradient(
          135deg,
          rgba(255, 255, 255, 0.7) 0%,
          rgba(255, 255, 255, 0.1) 30%,
          rgba(255, 255, 255, 0) 55%,
          rgba(255, 255, 255, 0.25) 100%
        );
        -webkit-mask:
          linear-gradient(#fff 0 0) content-box,
          linear-gradient(#fff 0 0);
        -webkit-mask-composite: xor;
        mask-composite: exclude;
        pointer-events: none;
      }

      /* one-shot diagonal sheen sweep on entrance */
      .tag .sheen {
        position: absolute;
        top: -80%;
        left: -140%;
        width: 55%;
        height: 260%;
        background: linear-gradient(
          120deg,
          rgba(255, 255, 255, 0.3) 0%,
          rgba(255, 255, 255, 0) 60%
        );
        transform: rotate(-16deg);
        pointer-events: none;
      }

      .tag-icon {
        position: relative;
        z-index: 1;
        flex: none;
        width: 52px;
        height: 52px;
        border-radius: 50%;
        display: flex;
        align-items: center;
        justify-content: center;
        background: linear-gradient(120deg, ${t.a1} 0%, ${t.a2} 50%, ${t.a3} 100%);
        box-shadow: 0 0 22px 2px rgba(207, 63, 196, 0.45);
      }

      .tag-icon svg {
        width: 26px;
        height: 26px;
        fill: #fff;
      }

      .tag-label {
        position: relative;
        z-index: 1;
        font-size: 32px;
        font-weight: 800;
        letter-spacing: 2px;
        text-transform: uppercase;
        color: #ffffff;
        white-space: nowrap;
        text-shadow: 0 2px 12px rgba(0, 0, 0, 0.35);
      }
    </style>
  </head>
  <body>
    <div
      id="root"
      data-composition-id="main"
      data-start="0"
      data-duration="${t.duration}"
      data-width="1920"
      data-height="1080"
      data-fps="60"
    >
      <div id="overlay-wrap" class="clip" data-start="0" data-duration="${t.duration}" data-track-index="1">
        <div class="tag-wrap" id="tag-wrap">
          <div class="tag" id="tag">
            <div class="sheen" id="sheen" data-layout-allow-overflow></div>
            <div class="tag-icon" id="tag-icon">
              <svg viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">${t.icon}</svg>
            </div>
            <div class="tag-label" id="tag-label">${t.label}</div>
          </div>
        </div>
      </div>
    </div>

    <script>
      window.__timelines = window.__timelines || {};
      const tl = gsap.timeline({ paused: true });

      // --- Entrance: panel lands, then icon, then label (staggered, never simultaneous) ---
      tl.fromTo(
        "#tag",
        { opacity: 0, x: -28, scale: 0.88 },
        { opacity: 1, x: 0, scale: 1, duration: 0.45, ease: "power3.out" },
        0,
      );
      tl.fromTo(
        "#sheen",
        { x: "0%" },
        { x: "260%", duration: 0.55, ease: "power2.out" },
        0.05,
      );
      tl.fromTo(
        "#tag-icon",
        { opacity: 0, scale: 0.4 },
        { opacity: 1, scale: 1, duration: 0.35, ease: "back.out(1.7)" },
        0.18,
      );
      tl.fromTo(
        "#tag-label",
        { opacity: 0, x: 14 },
        { opacity: 1, x: 0, duration: 0.35, ease: "power2.out" },
        0.3,
      );
${pulseBlock}

      // --- Exit ---
      tl.to(
        "#tag-wrap",
        { opacity: 0, y: -14, scale: 0.95, duration: 0.4, ease: "power2.in" },
        ${exitStart},
      );

      window.__timelines["main"] = tl;
    </script>
  </body>
</html>
`;
}

for (const t of TAGS) {
  const dir = path.join(ROOT, t.dir);
  fs.writeFileSync(path.join(dir, "index.html"), buildHtml(t), "utf-8");

  // meta.json
  fs.writeFileSync(
    path.join(dir, "meta.json"),
